import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import java.time.Duration

@Configuration
@EnableConfigurationProperties(ProxyCacheProperties::class)
class ProxyCacheConfig(
    private val properties: ProxyCacheProperties,
    private val cacheFactory: TieredCacheFactory,
) {
    @Bean
    fun categoryTieredCache(): TieredCache<Int, Category> =
        buildCache(properties.entity.category, Category::class.java) { it.id }

    @Bean
    fun brandTieredCache(): TieredCache<Long, Brand> =
        buildCache(properties.entity.brand, Brand::class.java) { it.id }

    @Bean
    fun manufacturerTieredCache(): TieredCache<Long, Manufacturer> =
        buildCache(properties.entity.manufacturer, Manufacturer::class.java) { it.id }

    @Bean
    fun mallTieredCache(): TieredCache<Int, Mall> =
        buildCache(properties.entity.mall, Mall::class.java) { it.mallId }

    private fun <ID : Any, V : Any> buildCache(
        entityConfig: ProxyCacheProperties.EntityCacheConfig,
        type: Class<V>,
        idExtractor: (V) -> ID,
    ): TieredCache<ID, V> =
        cacheFactory.create(
            type = type,
            idExtractor = idExtractor,
            keyPrefix = entityConfig.keyPrefix
                ?: "${properties.keyPrefixBase}.${type.simpleName.lowercase()}.cache",
            l1Ttl = Duration.ofMinutes(entityConfig.l1TtlMinutes ?: properties.l1.defaultTtlMinutes),
            l2Ttl = Duration.ofMinutes(entityConfig.l2TtlMinutes ?: properties.l2.defaultTtlMinutes),
            maxSize = properties.l1.maxSize,
        )
}"}

