import co.elastic.clients.elasticsearch.core.SearchRequest
import com.cowave.search.domain.document.CategoryBoostDocument
import com.cowave.search.domain.search.AttributeBoost
import com.cowave.search.domain.search.BoostingRepository
import com.cowave.search.domain.search.CategoryBoost
import com.cowave.search.outbound_adapter.search.factory.toSearchResult
import com.cowave.search.repository.cache.config.ValkeyBoostStore
import com.cowave.search.repository.elasticsearch.ElasticsearchTemplate
import org.springframework.stereotype.Component
import toAttributeBoosts
import toCategoryBoosts

@Component
class BoostingRepositoryImpl(
    private val esTemplate: ElasticsearchTemplate,
    private val valkeyBoostStore: ValkeyBoostStore,
    private val boostingProperties: BoostingProperties,
) : BoostingRepository {
    override fun getCategoryBoosts(keyword: String): List<CategoryBoost> {
        val normalizedKeyword = normalizeKeyword(keyword)

        return getCategoryBoostsFromValkey(normalizedKeyword)
            ?: searchCategoryBoostsFromEs(normalizedKeyword)
    }

    override fun getAttributeBoosts(keyword: String): List<AttributeBoost> {
        val normalizedKeyword = normalizeKeyword(keyword)

        return valkeyBoostStore
            .getAttributeBoosts(normalizedKeyword)
            ?.toAttributeBoosts()
            ?: emptyList()
    }

    private fun normalizeKeyword(keyword: String): String = keyword.replace(" ", "").lowercase()

    private fun getCategoryBoostsFromValkey(keyword: String): List<CategoryBoost>? =
        valkeyBoostStore.getCategoryBoosts(keyword)?.toCategoryBoosts()

    private fun searchCategoryBoostsFromEs(keyword: String): List<CategoryBoost> {
        val searchRequest = buildCategoryBoostQuery(keyword)

        return esTemplate
            .search(searchRequest, CategoryBoost::class.java)
            .toSearchResult()
            .documents
    }

    private fun buildCategoryBoostQuery(keyword: String): SearchRequest =
        SearchRequest
            .Builder()
            .index(boostingProperties.indexName)
            .query { q ->
                q.term { t ->
                    t
                        .field(CategoryBoostDocument::keyword.name)
                        .value(keyword)
                }
            }.source { s ->
                s.filter { f ->
                    f.includes(
                        CategoryBoostDocument::categoryCode.name,
                        CategoryBoostDocument::categoryDepth.name,
                        CategoryBoostDocument::weightScore.name,
                    )
                }
            }.build()
}"}

