import com.cowave.search.repository.cache.dto.AttributeBoostData
import com.cowave.search.repository.cache.dto.CategoryBoostData
import com.cowave.shared.utils.logger
import org.springframework.data.redis.core.RedisTemplate
import org.springframework.stereotype.Component

@Component
class ValkeyBoostStore(
    private val redisTemplate: RedisTemplate<String, String>,
) {
    companion object {
        private val log by logger()
        private const val CATEGORY_BOOST_KEY = "BOOSTKEYWORD:BOOST"
        private const val ATTRIBUTE_BOOST_KEY = "ATTRIBUTEVALUESEQ_BOOSTKEYWORD:BOOST"
    }

    fun getCategoryBoosts(keyword: String): List<CategoryBoostData>? =
        getBoostValue(keyword, CATEGORY_BOOST_KEY)?.let { value ->
            parseCategoryBoosts(value)
        }

    fun getAttributeBoosts(keyword: String): List<AttributeBoostData>? =
        getBoostValue(keyword, ATTRIBUTE_BOOST_KEY)?.let { value ->
            parseAttributeBoosts(value)
        }

    private fun getBoostValue(
        keyword: String,
        cacheKey: String,
    ): String? =
        runCatching {
            redisTemplate
                .opsForHash<String, String>()
                .get(cacheKey, keyword)
                ?.also { log.debug("Cache HIT [$cacheKey]: '$keyword'") }
                ?: run {
                    log.debug("Cache MISS [$cacheKey]: '$keyword'")
                    null
                }
        }.onFailure { e ->
            log.error("Cache ERROR [$cacheKey]: '$keyword'", e)
        }.getOrNull()

    private fun parseCategoryBoosts(value: String): List<CategoryBoostData> {
        if (value.isBlank()) return emptyList()

        return value.split(",").mapNotNull { item ->
            val parts = item.split("|")
            if (parts.size == 3) {
                CategoryBoostData(
                    code = parts[0],
                    depth = parts[1],
                    score = parts[2].toIntOrNull() ?: 0,
                )
            } else {
                log.warn("Invalid CategoryBoost format: '$item'")
                null
            }
        }
    }

    private fun parseAttributeBoosts(value: String): List<AttributeBoostData> {
        if (value.isBlank()) return emptyList()

        return value.split(",").mapNotNull { group ->
            val parts = group.split("|")
            if (parts.size >= 2) {
                AttributeBoostData(
                    attributeValueSeqs = parts.dropLast(1),
                    weight = parts.last().toIntOrNull() ?: 0,
                )
            } else {
                log.warn("Invalid AttributeBoost format: '$group'")
                null
            }
        }
    }
}"}

